/* Direct count modules differ in an i64.const operand and comparison opcode.
 * The i64.const uses canonical signed LEB128, up to five bytes for the
 * supported range. The code section and first body lengths grow with it. */
static size_t yx_count_sleb(uint32_t value, uint8_t *bytes)
{
    size_t length = 0;
    uint64_t remaining = value;
    do {
        uint8_t byte = (uint8_t) (remaining & 0x7f);
        bool done;
        remaining >>= 7;
        done = remaining == 0 && (byte & 0x40) == 0;
        if (!done) byte |= 0x80;
        if (bytes) bytes[length] = byte;
        ++length;
        if (done) break;
    } while (true);
    return length;
}

static uint8_t yx_count_wasm_opcode(yx_ser_count_op op)
{
    switch (op) {
    case YX_SER_COUNT_GT: return 0x55;
    case YX_SER_COUNT_GE: return 0x59;
    case YX_SER_COUNT_EQ: return 0x51;
    case YX_SER_COUNT_LT: return 0x53;
    case YX_SER_COUNT_LE: return 0x57;
    case YX_SER_COUNT_NE: return 0x52;
    default: return 0;
    }
}

static uint64_t yx_count_max_matches(yx_ser_count_op op, uint32_t value)
{
    if (op == YX_SER_COUNT_GE || op == YX_SER_COUNT_LT)
        return value > 0 ? value : 1;
    return (uint64_t) value + 1;
}

static bool yx_count_without_match_limit(yx_ser_count_op op, uint32_t value)
{
    return value == UINT32_MAX &&
        (op == YX_SER_COUNT_GT || op == YX_SER_COUNT_EQ ||
         op == YX_SER_COUNT_LE || op == YX_SER_COUNT_NE);
}

static bool yx_single_text_count_wasm_decode(const uint8_t *wasm,
                                              size_t length,
                                              yx_ser_count_op *op,
                                              uint32_t *value)
{
    const size_t base_length = sizeof(yx_single_text_count_gt_zero_wasm);
    size_t operand_length, extra;
    uint8_t canonical[5];
    uint64_t decoded_value = 0;
    if (length < base_length || length > base_length + 4 ||
        yx_single_text_count_gt_zero_wasm[194] != 0x32 ||
        yx_single_text_count_gt_zero_wasm[196] != 0x1f ||
        yx_single_text_count_gt_zero_wasm[213] != 0 ||
        yx_single_text_count_gt_zero_wasm[214] != 0x55)
        return false;
    extra = length - base_length;
    operand_length = extra + 1;
    if (memcmp(wasm, yx_single_text_count_gt_zero_wasm, 194) != 0 ||
        wasm[194] != (uint8_t) (0x32 + extra) ||
        wasm[195] != yx_single_text_count_gt_zero_wasm[195] ||
        wasm[196] != (uint8_t) (0x1f + extra) ||
        memcmp(wasm + 197, yx_single_text_count_gt_zero_wasm + 197,
               213 - 197) != 0 ||
        memcmp(wasm + 214 + operand_length,
               yx_single_text_count_gt_zero_wasm + 215,
               base_length - 215) != 0)
        return false;
    for (size_t i = 0; i < operand_length; ++i) {
        uint8_t byte = wasm[213 + i];
        if (((byte & 0x80) != 0) != (i + 1 < operand_length))
            return false;
        decoded_value |= (uint64_t) (byte & 0x7f) << (7 * i);
    }
    if (decoded_value > UINT32_MAX ||
        yx_count_sleb((uint32_t) decoded_value, canonical) !=
            operand_length ||
        memcmp(wasm + 213, canonical, operand_length) != 0)
        return false;
    for (yx_ser_count_op candidate = YX_SER_COUNT_GT;
         candidate <= YX_SER_COUNT_NE; ++candidate)
        if (wasm[213 + operand_length] ==
            yx_count_wasm_opcode(candidate)) {
            *op = candidate;
            *value = (uint32_t) decoded_value;
            return true;
        }
    return false;
}

static bool yx_wasm_has_pat_matches(const uint8_t *wasm, size_t length)
{
    static const uint8_t marker[] = "pat_matches";
    for (size_t i = 0; i + sizeof(marker) - 1 <= length; ++i)
        if (memcmp(wasm + i, marker, sizeof(marker) - 1) == 0)
            return true;
    return false;
}

static bool yx_wasm_has_pat_match_at(const uint8_t *wasm, size_t length)
{
    static const uint8_t marker[] = "is_pat_match_at";
    for (size_t i = 0; i + sizeof(marker) - 1 <= length; ++i)
        if (memcmp(wasm + i, marker, sizeof(marker) - 1) == 0)
            return true;
    return false;
}

static bool yx_single_text_at_wasm_decode(const uint8_t *wasm,
                                           size_t length, uint32_t *offset)
{
    const size_t base_length = sizeof(yx_single_text_at_zero_wasm);
    size_t operand_length;
    uint8_t canonical[5];
    uint64_t value = 0;
    if (length < base_length || length > base_length + 4 ||
        yx_single_text_at_zero_wasm[208] != 0x31 ||
        yx_single_text_at_zero_wasm[210] != 0x1e ||
        yx_single_text_at_zero_wasm[224] != 0x42 ||
        yx_single_text_at_zero_wasm[225] != 0 ||
        memcmp(wasm, yx_single_text_at_zero_wasm, 208) != 0)
        return false;
    operand_length = length - base_length + 1;
    if (wasm[208] != (uint8_t) (0x31 + operand_length - 1) ||
        wasm[209] != yx_single_text_at_zero_wasm[209] ||
        wasm[210] != (uint8_t) (0x1e + operand_length - 1) ||
        memcmp(wasm + 211, yx_single_text_at_zero_wasm + 211,
               225 - 211) != 0 ||
        memcmp(wasm + 225 + operand_length,
               yx_single_text_at_zero_wasm + 226,
               base_length - 226) != 0)
        return false;
    for (size_t i = 0; i < operand_length; ++i) {
        uint8_t byte = wasm[225 + i];
        if (((byte & 0x80) != 0) != (i + 1 < operand_length))
            return false;
        value |= (uint64_t) (byte & 0x7f) << (7 * i);
    }
    if (value > UINT32_MAX ||
        yx_count_sleb((uint32_t) value, canonical) != operand_length ||
        memcmp(wasm + 225, canonical, operand_length) != 0)
        return false;
    *offset = (uint32_t) value;
    return true;
}

/* `not $a` adds an i32.eqz after the pattern lookup. The WASM code
 * section and its containing function body each grow by one byte. */
static bool yx_make_negated_single_text_pattern_wasm(
    uint8_t result[sizeof(yx_single_text_pattern_wasm) + 1])
{
    const size_t insert_at = 263;
    if (sizeof(yx_single_text_pattern_wasm) != 293 ||
        yx_single_text_pattern_wasm[215] != 0x4d ||
        yx_single_text_pattern_wasm[247] != 0x1c ||
        yx_single_text_pattern_wasm[insert_at] != 0x0b)
        return false;
    memcpy(result, yx_single_text_pattern_wasm, insert_at);
    result[insert_at] = 0x45;
    memcpy(result + insert_at + 1,
           yx_single_text_pattern_wasm + insert_at,
           sizeof(yx_single_text_pattern_wasm) - insert_at);
    result[215] = 0x4e;
    result[247] = 0x1d;
    return true;
}

