static bool yx_is_numeric_of_wasm(const uint8_t *wasm, size_t length,
                                   uint8_t *pattern_count,
                                   uint8_t *required)
{
    if (!wasm || length != sizeof(yx_numeric_of_wasm) ||
        yx_numeric_of_wasm[251] != 1 || yx_numeric_of_wasm[253] != 2 ||
        wasm[251] < 1 || wasm[251] > 3 ||
        wasm[253] < 1 || wasm[253] > wasm[251] + 1 ||
        memcmp(wasm, yx_numeric_of_wasm, 251) != 0 ||
        wasm[252] != yx_numeric_of_wasm[252] ||
        memcmp(wasm + 254, yx_numeric_of_wasm + 254,
               length - 254) != 0)
        return false;
    if (pattern_count) *pattern_count = wasm[251] + 1;
    if (required) *required = wasm[253];
    return true;
}

