static uint8_t yx_for_any_wasm_pattern_count(const uint8_t *wasm,
                                              size_t length)
{
    if (!wasm) return 0;
    if (length == sizeof(yx_for_any_one_wasm) &&
        memcmp(wasm, yx_for_any_one_wasm, length) == 0) return 1;
    if (length == sizeof(yx_for_any_two_wasm) &&
        memcmp(wasm, yx_for_any_two_wasm, length) == 0) return 2;
    if (length == sizeof(yx_for_any_three_wasm) &&
        memcmp(wasm, yx_for_any_three_wasm, length) == 0) return 3;
    if (length == sizeof(yx_for_any_four_wasm) &&
        memcmp(wasm, yx_for_any_four_wasm, length) == 0) return 4;
    return 0;
}

/* A one-pattern `for none of them : ( $ )` loop differs from `for any`
 * only in its two result constants. Check every other byte before accepting
 * the variant; this also keeps malformed WASM outside the supported shape. */
static bool yx_is_for_none_one_wasm(const uint8_t *wasm, size_t length)
{
    const size_t first = 377, second = 476;
    return wasm && length == sizeof(yx_for_any_one_wasm) &&
           yx_for_any_one_wasm[first] == 1 &&
           yx_for_any_one_wasm[second] == 0 &&
           wasm[first] == 0 && wasm[second] == 1 &&
           memcmp(wasm, yx_for_any_one_wasm, first) == 0 &&
           memcmp(wasm + first + 1, yx_for_any_one_wasm + first + 1,
                  second - first - 1) == 0 &&
           memcmp(wasm + second + 1, yx_for_any_one_wasm + second + 1,
                  length - second - 1) == 0;
}

