/* The five-pattern any-of program changes only the last PatternId in the
 * four-pattern any-of program (3 to 4). */
static bool yx_is_five_text_any_wasm(const uint8_t *wasm, size_t length)
{
    const size_t id = YX_FIVE_ANY_LAST_PATTERN_ID;
    return length == sizeof(yx_four_text_any_wasm) &&
           yx_four_text_any_wasm[id] == 3 && wasm[id] == 4 &&
           memcmp(wasm, yx_four_text_any_wasm, id) == 0 &&
           memcmp(wasm + id + 1, yx_four_text_any_wasm + id + 1,
                  length - id - 1) == 0;
}

