/* Reversing the expression order changes only the two WASM PatternIds. */
static bool yx_is_reversed_two_text_wasm(const uint8_t *wasm,
                                         size_t wasm_length,
                                         const uint8_t *forward,
                                         size_t forward_length,
                                         size_t lhs_id, size_t rhs_id)
{
    if (wasm_length != forward_length || lhs_id >= forward_length ||
        rhs_id >= forward_length || forward[lhs_id] != 0 ||
        forward[rhs_id] != 1) return false;
    for (size_t i = 0; i < wasm_length; ++i) {
        uint8_t expected = i == lhs_id ? 1
                         : i == rhs_id ? 0 : forward[i];
        if (wasm[i] != expected) return false;
    }
    return true;
}

/* Identical patterns share one PatternId, including both condition operands. */
static bool yx_is_duplicate_two_text_wasm(const uint8_t *wasm,
                                          size_t wasm_length,
                                          const uint8_t *forward,
                                          size_t forward_length,
                                          size_t rhs_id)
{
    if (wasm_length != forward_length || rhs_id >= forward_length ||
        forward[rhs_id] != 1 || wasm[rhs_id] != 0) return false;
    for (size_t i = 0; i < wasm_length; ++i)
        if (i != rhs_id && wasm[i] != forward[i]) return false;
    return true;
}

/* `any of them` with two aliases uses YARA-X's one-PatternId WASM path. */
static const uint8_t yx_duplicate_two_any_patch[] = {
    0x23, 0x01, 0x04, 0x40, 0x05, 0x10, 0x01, 0x0b, 0x02, 0x7f, 0x41,
    0x00, 0x10, 0x03, 0x04, 0x40, 0x41, 0x01, 0x0c, 0x01, 0x05
};

static bool yx_is_duplicate_two_any_wasm(const uint8_t *wasm,
                                         size_t wasm_length)
{
    const size_t patch_offset = 221;
    if (wasm_length != sizeof(yx_two_text_and_wasm) ||
        patch_offset + sizeof(yx_duplicate_two_any_patch) > wasm_length ||
        yx_two_text_and_wasm[YX_TWO_AND_RHS_PATTERN_ID] != 1)
        return false;
    for (size_t i = 0; i < wasm_length; ++i) {
        uint8_t expected = i == YX_TWO_AND_RHS_PATTERN_ID ? 0
            : i >= patch_offset &&
              i < patch_offset + sizeof(yx_duplicate_two_any_patch)
            ? yx_duplicate_two_any_patch[i - patch_offset]
            : yx_two_text_and_wasm[i];
        if (wasm[i] != expected) return false;
    }
    return true;
}

static bool yx_is_mixed_single_text_wasm(const uint8_t *wasm,
                                          size_t wasm_length,
                                          const uint8_t *template_wasm,
                                          size_t template_length,
                                          size_t truth_offset, bool *truth)
{
    if (wasm_length != template_length ||
        truth_offset >= template_length ||
        template_wasm[truth_offset] != 1 || wasm[truth_offset] > 1)
        return false;
    for (size_t i = 0; i < wasm_length; ++i)
        if (i != truth_offset && wasm[i] != template_wasm[i]) return false;
    *truth = wasm[truth_offset] != 0;
    return true;
}

static bool yx_is_ordered_text_wasm(const uint8_t *wasm,
                                    size_t wasm_length,
                                    const uint8_t *forward,
                                    size_t forward_length,
                                    const size_t *offsets, uint8_t *order,
                                    size_t pattern_count)
{
    uint8_t found[5];
    bool seen[5] = {false, false, false, false, false};
    if (wasm_length != forward_length || pattern_count < 3 ||
        pattern_count > 5) return false;
    for (size_t j = 0; j < pattern_count; ++j) {
        if (offsets[j] >= forward_length || forward[offsets[j]] != j ||
            wasm[offsets[j]] >= pattern_count ||
            seen[wasm[offsets[j]]]) return false;
        found[j] = wasm[offsets[j]];
        seen[found[j]] = true;
    }
    for (size_t i = 0; i < wasm_length; ++i) {
        uint8_t expected = forward[i];
        for (size_t j = 0; j < pattern_count; ++j)
            if (i == offsets[j]) { expected = found[j]; break; }
        if (wasm[i] != expected) return false;
    }
    memcpy(order, found, pattern_count);
    return true;
}

