static bool yx_is_pe_or_filesize_wasm(const uint8_t *wasm, size_t length,
                                      const uint8_t *code, size_t code_length)
{
    const size_t offset = YX_PE_OR_SPLICE_OFFSET;
    const size_t tail = offset + YX_PE_OR_OLD_SPAN;
    const size_t new_tail = offset + code_length;
    return tail <= sizeof(yx_pe_is_pe_filesize_wasm) &&
           length == sizeof(yx_pe_is_pe_filesize_wasm) -
                     YX_PE_OR_OLD_SPAN + code_length &&
           memcmp(wasm, yx_pe_is_pe_filesize_wasm, offset) == 0 &&
           memcmp(wasm + offset, code, code_length) == 0 &&
           memcmp(wasm + new_tail, yx_pe_is_pe_filesize_wasm + tail,
                  length - new_tail) == 0;
}

static bool yx_is_pe_compare_one_wasm(const uint8_t *wasm, size_t length,
                                       const uint8_t *template_wasm,
                                       size_t template_length,
                                       size_t comparison, uint8_t opcode)
{
    return length == template_length && comparison + 1 < length &&
           wasm[comparison] == 1 && wasm[comparison + 1] == opcode &&
           template_wasm[comparison] == 0 &&
           template_wasm[comparison + 1] == 0x55 &&
           memcmp(wasm, template_wasm, comparison) == 0 &&
           memcmp(wasm + comparison + 2, template_wasm + comparison + 2,
                  length - comparison - 2) == 0;
}

