typedef struct yx_writer {
    uint8_t *data;
    size_t used;
    size_t capacity;
} yx_writer;

typedef struct yx_reader {
    const uint8_t *data;
    size_t length;
    size_t at;
    bool malformed;
    bool no_memory;
} yx_reader;

static bool yx_put_bytes(yx_writer *w, const void *data, size_t length)
{
    if (length > SIZE_MAX - w->used) return false;
    if (length > w->capacity - w->used) {
        size_t required = w->used + length;
        /* Thompson compilation builds many small writers: start small. */
        size_t capacity = w->capacity ? w->capacity : 64;
        uint8_t *grown;
        while (capacity < required) {
            if (capacity > SIZE_MAX / 2) {
                capacity = required;
                break;
            }
            capacity *= 2;
        }
        grown = realloc(w->data, capacity);
        if (!grown) return false;
        w->data = grown;
        w->capacity = capacity;
    }
    if (length) memcpy(w->data + w->used, data, length);
    w->used += length;
    return true;
}

static bool yx_put_u8(yx_writer *w, uint8_t value)
{
    return yx_put_bytes(w, &value, 1);
}

/* bincode 2's standard varint representation, used for usize and IDs. */
static bool yx_put_uint(yx_writer *w, uint64_t value)
{
    uint8_t bytes[9];
    size_t length;
    if (value < 251) return yx_put_u8(w, (uint8_t) value);
    if (value <= UINT16_MAX) {
        bytes[0] = 251;
        length = 2;
    } else if (value <= UINT32_MAX) {
        bytes[0] = 252;
        length = 4;
    } else {
        bytes[0] = 253;
        length = 8;
    }
    for (size_t i = 0; i < length; ++i)
        bytes[i + 1] = (uint8_t) (value >> (8 * i));
    return yx_put_bytes(w, bytes, length + 1);
}

static bool yx_put_string(yx_writer *w, const char *string)
{
    size_t length = strlen(string);
    return yx_put_uint(w, (uint64_t) length) &&
           yx_put_bytes(w, string, length);
}

static bool yx_put_signed(yx_writer *w, int64_t value)
{
    uint64_t zigzag = value >= 0
        ? (uint64_t) value * 2
        : (uint64_t) (-(value + 1)) * 2 + 1;
    return yx_put_uint(w, zigzag);
}

static bool yx_put_float(yx_writer *w, double value)
{
    uint64_t bits;
    uint8_t bytes[8];
    if (sizeof(value) != 8 || DBL_MANT_DIG != 53 || FLT_RADIX != 2)
        return false;
    memcpy(&bits, &value, sizeof(bits));
    for (size_t i = 0; i < 8; ++i)
        bytes[i] = (uint8_t) (bits >> (i * 8));
    return yx_put_bytes(w, bytes, sizeof(bytes));
}

static bool yx_module_globals(const char *const *chunks, size_t chunk_count,
                               uint8_t *output, size_t output_length)
{
    uint32_t bits = 0;
    unsigned pending = 0;
    size_t used = 0;
    for (size_t chunk = 0; chunk < chunk_count; ++chunk) {
        for (const char *at = chunks[chunk]; *at; ++at) {
            unsigned char ch = (unsigned char) *at;
            uint32_t digit;
            if (ch >= 'A' && ch <= 'Z') digit = ch - 'A';
            else if (ch >= 'a' && ch <= 'z') digit = ch - 'a' + 26;
            else if (ch >= '0' && ch <= '9') digit = ch - '0' + 52;
            else if (ch == '+') digit = 62;
            else if (ch == '/') digit = 63;
            else return false;
            bits = (bits << 6) | digit;
            pending += 6;
            if (pending >= 8) {
                pending -= 8;
                if (used == output_length) return false;
                output[used++] = (uint8_t) (bits >> pending);
                bits &= (UINT32_C(1) << pending) - 1;
            }
        }
    }
    return used == output_length && bits == 0 && pending < 6;
}

static bool yx_pe_globals(uint8_t output[YX_PE_GLOBALS_LENGTH])
{
    return yx_module_globals(yx_pe_globals_b64,
                             sizeof(yx_pe_globals_b64) /
                                 sizeof(yx_pe_globals_b64[0]),
                             output, YX_PE_GLOBALS_LENGTH);
}

