static bool yx_get_u8(yx_reader *r, uint8_t *value)
{
    if (!r->data || r->at >= r->length) {
        r->malformed = true;
        return false;
    }
    *value = r->data[r->at++];
    return true;
}

static bool yx_get_uint(yx_reader *r, uint64_t *value)
{
    uint8_t marker;
    size_t length;
    uint64_t result = 0;
    if (!yx_get_u8(r, &marker)) return false;
    if (marker < 251) {
        *value = marker;
        return true;
    }
    if (marker == 251) length = 2;
    else if (marker == 252) length = 4;
    else if (marker == 253) length = 8;
    else {
        r->malformed = true;
        return false;
    }
    if (!r->data || r->at > r->length ||
        length > r->length - r->at) {
        r->malformed = true;
        return false;
    }
    for (size_t i = 0; i < length; ++i)
        result |= (uint64_t) r->data[r->at++] << (8 * i);
    *value = result;
    return true;
}

static bool yx_valid_utf8(const uint8_t *bytes, size_t length);

static bool yx_get_string(yx_reader *r, char **string)
{
    uint64_t length;
    char *copy;
    if (!yx_get_uint(r, &length)) return false;
    if (!r->data || r->at > r->length || length > SIZE_MAX - 1 ||
        length > r->length - r->at ||
        memchr(r->data + r->at, 0, (size_t) length) ||
        !yx_valid_utf8(r->data + r->at, (size_t) length)) {
        r->malformed = true;
        return false;
    }
    copy = malloc((size_t) length + 1);
    if (!copy) {
        r->no_memory = true;
        return false;
    }
    memcpy(copy, r->data + r->at, (size_t) length);
    copy[length] = 0;
    r->at += (size_t) length;
    *string = copy;
    return true;
}

bool yx_ser_ascii_pool_utf8_error(const uint8_t *data, size_t length,
                                  size_t *valid_up_to)
{
    static const uint8_t header[12] =
        {'Y','A','R','A','-','X',0,0,12,0,0,0};
    yx_reader r = {data, length, sizeof(header), false, false};
    uint64_t count, width;
    if (!data || !valid_up_to || length < sizeof(header) ||
        memcmp(data, header, sizeof(header)) != 0 ||
        !yx_get_uint(&r, &count) || count < 1 || count > 32)
        return false;
    for (uint64_t i = 0; i < count; ++i) {
        size_t invalid_at = SIZE_MAX;
        if (!yx_get_uint(&r, &width) || width > 128 ||
            width > r.length - r.at)
            return false;
        for (size_t j = 0; j < (size_t) width; ++j) {
            uint8_t byte = r.data[r.at + j];
            if (byte >= 0x80 && byte <= 0xbf) {
                if (invalid_at != SIZE_MAX) return false;
                invalid_at = j;
            } else if (byte == 0 || byte >= 0x80) {
                return false;
            }
        }
        if (invalid_at != SIZE_MAX) {
            *valid_up_to = invalid_at;
            return true;
        }
        r.at += (size_t) width;
    }
    return false;
}

typedef enum yx_prefix_uint_result {
    YX_PREFIX_UINT_INVALID,
    YX_PREFIX_UINT_VALUE,
    YX_PREFIX_UINT_TRUNCATED
} yx_prefix_uint_result;

static yx_prefix_uint_result yx_prefix_read_uint(
    const uint8_t *data, size_t length, size_t *at,
    uint64_t *value, size_t *additional)
{
    uint8_t marker;
    size_t width;
    uint64_t decoded = 0;
    if (*at >= length) {
        *additional = 1;
        return YX_PREFIX_UINT_TRUNCATED;
    }
    marker = data[(*at)++];
    if (marker < 251) {
        *value = marker;
        return YX_PREFIX_UINT_VALUE;
    }
    if (marker == 251) width = 2;
    else if (marker == 252) width = 4;
    else if (marker == 253) width = 8;
    else return YX_PREFIX_UINT_INVALID;
    if (width > length - *at) {
        *additional = width - (length - *at);
        return YX_PREFIX_UINT_TRUNCATED;
    }
    for (size_t i = 0; i < width; ++i)
        decoded |= (uint64_t) data[(*at)++] << (8 * i);
    *value = decoded;
    return YX_PREFIX_UINT_VALUE;
}

/* bincode reports the bytes missing from a partially read string or integer,
 * but reports one byte while reading an incomplete WASM byte vector. Limit
 * this diagnosis to the canonical small-archive prefix layout: default
 * namespace, two or three ASCII pool strings, no regexp pool, and at most
 * one short literal. Invalid preceding fields are never called truncations. */
bool yx_ser_short_prefix_truncation(const uint8_t *data, size_t length,
                                    size_t *additional)
{
    static const uint8_t header[12] =
        {'Y','A','R','A','-','X',0,0,12,0,0,0};
    static const uint8_t wasm_header[8] =
        {0, 'a', 's', 'm', 1, 0, 0, 0};
    const char namespace_name[] = "default";
    size_t at = sizeof(header), available;
    uint64_t pool_count, width, value;
    yx_prefix_uint_result result;
    if (!data || !additional || length < sizeof(header) ||
        memcmp(data, header, sizeof(header)) != 0)
        return false;
    *additional = 0;
    result = yx_prefix_read_uint(data, length, &at, &pool_count,
                                 additional);
    if (result == YX_PREFIX_UINT_TRUNCATED) return true;
    if (result != YX_PREFIX_UINT_VALUE || pool_count < 2 ||
        pool_count > 65536) return false;
    for (uint64_t i = 0; i < pool_count; ++i) {
        result = yx_prefix_read_uint(data, length, &at, &width,
                                     additional);
        if (result == YX_PREFIX_UINT_TRUNCATED) return true;
        if (result != YX_PREFIX_UINT_VALUE || width == 0 ||
            width > (i == 0 ? 7u : 4096u) ||
            (i == 0 && width != 7)) return false;
        available = length - at;
        if (available > width) available = (size_t) width;
        if (i == 0) {
            if (memcmp(data + at, namespace_name, available) != 0)
                return false;
        } else {
            for (size_t j = 0; j < available; ++j)
                if (data[at + j] < 33 || data[at + j] > 126)
                    return false;
        }
        if (available < width) {
            *additional = (size_t) width - available;
            return true;
        }
        at += (size_t) width;
    }
    for (size_t i = 0; i < 2; ++i) {
        result = yx_prefix_read_uint(data, length, &at, &value,
                                     additional);
        if (result == YX_PREFIX_UINT_TRUNCATED) return true;
        if (result != YX_PREFIX_UINT_VALUE || value != 0) return false;
    }
    result = yx_prefix_read_uint(data, length, &at, &value, additional);
    if (result == YX_PREFIX_UINT_TRUNCATED) return true;
    if (result != YX_PREFIX_UINT_VALUE || value > 65536) return false;
    for (uint64_t i = 0; i < value; ++i) {
        result = yx_prefix_read_uint(data, length, &at, &width,
                                     additional);
        if (result == YX_PREFIX_UINT_TRUNCATED) return true;
        if (result != YX_PREFIX_UINT_VALUE || width > (uint64_t)1 << 20)
            return false;
        available = length - at;
        if (available < width) {
            *additional = (size_t) width - available;
            return true;
        }
        at += (size_t) width;
    }
    result = yx_prefix_read_uint(data, length, &at, &width, additional);
    if (result == YX_PREFIX_UINT_TRUNCATED) return true;
    if (result != YX_PREFIX_UINT_VALUE || width < sizeof(wasm_header) ||
        width > (uint64_t)1 << 30) return false;
    available = length - at;
    if (available >= width) return false;
    if (memcmp(data + at, wasm_header,
               available < sizeof(wasm_header) ? available :
               sizeof(wasm_header)) != 0) return false;
    *additional = 1;
    return true;
}

static bool yx_get_signed(yx_reader *r, int64_t *value)
{
    uint64_t zigzag;
    if (!yx_get_uint(r, &zigzag)) return false;
    if (zigzag & 1)
        *value = -(int64_t) (zigzag >> 1) - 1;
    else
        *value = (int64_t) (zigzag >> 1);
    return true;
}

static bool yx_get_float(yx_reader *r, double *value)
{
    uint64_t bits = 0;
    if (sizeof(*value) != 8 || DBL_MANT_DIG != 53 || FLT_RADIX != 2)
        return false;
    if (!r->data || r->at > r->length || r->length - r->at < 8) {
        r->malformed = true;
        return false;
    }
    for (size_t i = 0; i < 8; ++i)
        bits |= (uint64_t) r->data[r->at++] << (i * 8);
    memcpy(value, &bits, sizeof(bits));
    return true;
}

typedef struct yx_bool_parser {
    const unsigned char *at;
    unsigned depth;
} yx_bool_parser;

static void yx_bool_skip_space(yx_bool_parser *parser)
{
    for (;;) {
        while (isspace(*parser->at)) ++parser->at;
        if (parser->at[0] == '/' && parser->at[1] == '/') {
            parser->at += 2;
            while (*parser->at && *parser->at != '\n') ++parser->at;
        } else if (parser->at[0] == '/' && parser->at[1] == '*') {
            const unsigned char *start = parser->at;
            parser->at += 2;
            while (*parser->at &&
                   !(parser->at[0] == '*' && parser->at[1] == '/'))
                ++parser->at;
            if (!*parser->at) {
                parser->at = start; /* Let the caller reject the comment. */
                return;
            }
            parser->at += 2;
        } else {
            return;
        }
    }
}

static bool yx_bool_keyword(yx_bool_parser *parser, const char *keyword)
{
    size_t length = strlen(keyword);
    yx_bool_skip_space(parser);
    if (strncmp((const char *) parser->at, keyword, length) != 0 ||
        (isalnum(parser->at[length]) || parser->at[length] == '_'))
        return false;
    parser->at += length;
    return true;
}

static bool yx_bool_parse_or(yx_bool_parser *parser, bool *truth);

static bool yx_bool_parse_primary(yx_bool_parser *parser, bool *truth)
{
    yx_bool_skip_space(parser);
    if (*parser->at == '(') {
        ++parser->at;
        if (++parser->depth > 256) return false;
        if (!yx_bool_parse_or(parser, truth)) return false;
        --parser->depth;
        yx_bool_skip_space(parser);
        if (*parser->at != ')') return false;
        ++parser->at;
        return true;
    }
    if (yx_bool_keyword(parser, "true")) {
        *truth = true;
        return true;
    }
    if (yx_bool_keyword(parser, "false")) {
        *truth = false;
        return true;
    }
    return false;
}

static bool yx_bool_parse_not(yx_bool_parser *parser, bool *truth)
{
    yx_bool_skip_space(parser);
    if (yx_bool_keyword(parser, "not")) {
        if (++parser->depth > 256) return false;
        if (!yx_bool_parse_not(parser, truth)) return false;
        --parser->depth;
        *truth = !*truth;
        return true;
    }
    return yx_bool_parse_primary(parser, truth);
}

static bool yx_bool_parse_and(yx_bool_parser *parser, bool *truth)
{
    bool right;
    if (!yx_bool_parse_not(parser, truth)) return false;
    while (yx_bool_keyword(parser, "and")) {
        if (!yx_bool_parse_not(parser, &right)) return false;
        *truth = *truth && right;
    }
    return true;
}

static bool yx_bool_parse_or(yx_bool_parser *parser, bool *truth)
{
    bool right;
    if (!yx_bool_parse_and(parser, truth)) return false;
    while (yx_bool_keyword(parser, "or")) {
        if (!yx_bool_parse_and(parser, &right)) return false;
        *truth = *truth || right;
    }
    return true;
}

/* YARA-X folds boolean-only expressions to the same WASM as true/false.
 * Keep this intentionally narrow: numeric constants and comparisons currently
 * generate different WASM, even when their result is constant. */
static bool yx_condition_constant_bool(const char *condition, bool *truth)
{
    yx_bool_parser parser;
    if (!condition) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    if (!yx_bool_parse_or(&parser, truth)) return false;
    yx_bool_skip_space(&parser);
    return *parser.at == 0;
}

static bool yx_condition_first_rule(const char *condition,
                                    const char *identifier)
{
    yx_bool_parser parser;
    size_t length;
    if (!condition || !identifier) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    yx_bool_skip_space(&parser);
    length = strlen(identifier);
    if (strncmp((const char *) parser.at, identifier, length) != 0 ||
        (isalnum(parser.at[length]) || parser.at[length] == '_'))
        return false;
    parser.at += length;
    yx_bool_skip_space(&parser);
    return *parser.at == 0;
}

/* In a boolean context YARA-X lowers a bare integer to `integer != 0`.
 * Restrict this parser to literal operands so the emitted WASM has a fully
 * predictable shape. The compiler has already validated the source. */
static bool yx_integer_literal(yx_bool_parser *parser, int64_t *value)
{
    const unsigned char *start = parser->at;
    uint64_t magnitude = 0;
    uint64_t limit;
    unsigned base = 10;
    bool negative = false;
    bool digits = false;
    yx_bool_skip_space(parser);
    if (*parser->at == '-') {
        negative = true;
        ++parser->at;
    }
    if (parser->at[0] == '0' &&
        (parser->at[1] == 'x' || parser->at[1] == 'X')) {
        base = 16;
        parser->at += 2;
    } else if (parser->at[0] == '0' &&
               (parser->at[1] == 'o' || parser->at[1] == 'O')) {
        base = 8;
        parser->at += 2;
    }
    limit = negative ? (uint64_t) INT64_MAX + 1 : (uint64_t) INT64_MAX;
    for (;;) {
        unsigned char c = *parser->at;
        unsigned digit;
        if (c == '_' && digits) {
            ++parser->at;
            continue;
        }
        if (c >= '0' && c <= '9') digit = c - '0';
        else if (base == 16 && c >= 'a' && c <= 'f') digit = c - 'a' + 10;
        else if (base == 16 && c >= 'A' && c <= 'F') digit = c - 'A' + 10;
        else break;
        if (digit >= base || magnitude > (limit - digit) / base) {
            parser->at = start;
            return false;
        }
        magnitude = magnitude * base + digit;
        digits = true;
        ++parser->at;
    }
    if (!digits) {
        parser->at = start;
        return false;
    }
    if (negative)
        *value = magnitude == (uint64_t) INT64_MAX + 1
            ? INT64_MIN : -(int64_t) magnitude;
    else
        *value = (int64_t) magnitude;
    return true;
}

/* YARA-X folds literal addition, subtraction, multiplication and bitwise
 * operators before lowering to WASM. Parse these by precedence, including
 * grouped subexpressions. Division/remainder remain runtime operations;
 * reject them, undefined operations and overflow rather than changing WASM. */
static bool yx_integer_constant(yx_bool_parser *parser, int64_t *value);

static bool yx_integer_primary(yx_bool_parser *parser, int64_t *value)
{
    const unsigned char *start;
    unsigned char sign;
    yx_bool_skip_space(parser);
    start = parser->at;
    if (yx_integer_literal(parser, value)) return true;
    parser->at = start;
    sign = *parser->at;
    if (sign == '+' || sign == '-' || sign == '~') {
        ++parser->at;
        if (++parser->depth > 256 ||
            !yx_integer_primary(parser, value)) return false;
        --parser->depth;
        if (sign == '-') {
            if (*value == INT64_MIN) return false;
            *value = -*value;
        } else if (sign == '~') *value = ~*value;
        return true;
    }
    if (sign != '(') return false;
    ++parser->at;
    if (++parser->depth > 256 ||
        !yx_integer_constant(parser, value)) return false;
    --parser->depth;
    yx_bool_skip_space(parser);
    if (*parser->at != ')') return false;
    ++parser->at;
    return true;
}

static bool yx_integer_multiplicative(yx_bool_parser *parser, int64_t *value)
{
    int64_t right;
    if (!yx_integer_primary(parser, value)) return false;
    for (;;) {
        yx_bool_skip_space(parser);
        /* Division and remainder deliberately remain runtime operations in
         * the reference IR, even when both operands are literals. */
        if (*parser->at != '*') return true;
        ++parser->at;
        if (!yx_integer_primary(parser, &right)) return false;
        if ((*value > 0 && right > 0 && *value > INT64_MAX / right) ||
            (*value > 0 && right < 0 && right < INT64_MIN / *value) ||
            (*value < 0 && right > 0 && *value < INT64_MIN / right) ||
            (*value < 0 && right < 0 && *value < INT64_MAX / right))
            return false;
        *value *= right;
    }
}

static bool yx_integer_additive(yx_bool_parser *parser, int64_t *value)
{
    int64_t right;
    unsigned char operation;
    if (!yx_integer_multiplicative(parser, value)) return false;
    for (;;) {
        yx_bool_skip_space(parser);
        operation = *parser->at;
        if (operation != '+' && operation != '-') return true;
        ++parser->at;
        if (!yx_integer_multiplicative(parser, &right)) return false;
        if (operation == '+') {
            if ((right > 0 && *value > INT64_MAX - right) ||
                (right < 0 && *value < INT64_MIN - right)) return false;
            *value += right;
        } else {
            if ((right < 0 && *value > INT64_MAX + right) ||
                (right > 0 && *value < INT64_MIN + right)) return false;
            *value -= right;
        }
    }
}

static int64_t yx_integer_signed_bits(uint64_t bits)
{
    return bits <= INT64_MAX ? (int64_t)bits :
           -1 - (int64_t)(UINT64_MAX - bits);
}

static bool yx_integer_shift(yx_bool_parser *parser, int64_t *value)
{
    int64_t right;
    if (!yx_integer_additive(parser, value)) return false;
    for (;;) {
        unsigned char operation;
        uint64_t bits;
        yx_bool_skip_space(parser);
        operation = *parser->at;
        if ((operation != '<' && operation != '>') || parser->at[1] != operation)
            return true;
        parser->at += 2;
        if (!yx_integer_additive(parser, &right) || right < 0) return false;
        if (right >= 64) { *value = 0; continue; }
        bits = (uint64_t)*value;
        if (operation == '<') bits <<= (unsigned)right;
        else if (right) {
            bits >>= (unsigned)right;
            if (*value < 0) bits |= UINT64_MAX << (64u - (unsigned)right);
        }
        *value = yx_integer_signed_bits(bits);
    }
}

static bool yx_integer_bitand(yx_bool_parser *parser, int64_t *value)
{
    int64_t right;
    if (!yx_integer_shift(parser, value)) return false;
    for (;;) {
        yx_bool_skip_space(parser);
        if (*parser->at != '&') return true;
        ++parser->at;
        if (!yx_integer_shift(parser, &right)) return false;
        *value &= right;
    }
}

static bool yx_integer_bitxor(yx_bool_parser *parser, int64_t *value)
{
    int64_t right;
    if (!yx_integer_bitand(parser, value)) return false;
    for (;;) {
        yx_bool_skip_space(parser);
        if (*parser->at != '^') return true;
        ++parser->at;
        if (!yx_integer_bitand(parser, &right)) return false;
        *value ^= right;
    }
}

static bool yx_integer_constant(yx_bool_parser *parser, int64_t *value)
{
    int64_t right;
    if (!yx_integer_bitxor(parser, value)) return false;
    for (;;) {
        yx_bool_skip_space(parser);
        if (*parser->at != '|') return true;
        ++parser->at;
        if (!yx_integer_bitxor(parser, &right)) return false;
        *value |= right;
    }
}

static bool yx_with_identifier(yx_bool_parser *parser,
                               const unsigned char **start, size_t *length)
{
    const unsigned char *at;
    yx_bool_skip_space(parser);
    at = parser->at;
    if (!((*at >= 'a' && *at <= 'z') ||
          (*at >= 'A' && *at <= 'Z') || *at == '_'))
        return false;
    for (++parser->at;
         (*parser->at >= 'a' && *parser->at <= 'z') ||
         (*parser->at >= 'A' && *parser->at <= 'Z') ||
         (*parser->at >= '0' && *parser->at <= '9') ||
         *parser->at == '_'; ++parser->at) {}
    *start = at;
    *length = (size_t) (parser->at - at);
    return true;
}

/* One integer binding, used as the left operand of a direct equality.
 * Keep the values in the one-byte signed LEB range of the verified WASM
 * templates. The optional first-rule conjunct has its own WASM layout. */
static bool yx_condition_single_with(const char *condition,
                                      const char *first_rule,
                                      bool *and_first_rule,
                                      int8_t *bound_value,
                                      int8_t *compared_value)
{
    yx_bool_parser parser;
    const unsigned char *name, *used_name;
    size_t name_length, used_length;
    int64_t bound, compared;
    bool and_reference = false;
    if (!condition || !and_first_rule || !bound_value ||
        !compared_value) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    yx_bool_skip_space(&parser);
    if (first_rule) {
        size_t length = strlen(first_rule);
        if (strncmp((const char *) parser.at, first_rule, length) == 0 &&
            !(isalnum(parser.at[length]) || parser.at[length] == '_')) {
            parser.at += length;
            if (!yx_bool_keyword(&parser, "and")) return false;
            and_reference = true;
        }
    }
    if (!yx_bool_keyword(&parser, "with") ||
        !yx_with_identifier(&parser, &name, &name_length)) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at++ != '=') return false;
    if (!yx_integer_constant(&parser, &bound)) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at++ != ':') return false;
    yx_bool_skip_space(&parser);
    if (*parser.at++ != '(' ||
        !yx_with_identifier(&parser, &used_name, &used_length) ||
        used_length != name_length ||
        memcmp(used_name, name, name_length) != 0) return false;
    yx_bool_skip_space(&parser);
    if (parser.at[0] != '=' || parser.at[1] != '=') return false;
    parser.at += 2;
    if (!yx_integer_constant(&parser, &compared)) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at++ != ')') return false;
    yx_bool_skip_space(&parser);
    if (*parser.at || bound < -64 || bound > 63 ||
        compared < -64 || compared > 63) return false;
    *and_first_rule = and_reference;
    *bound_value = (int8_t) bound;
    *compared_value = (int8_t) compared;
    return true;
}

static bool yx_condition_integer(const char *condition,
                                 yx_ser_rule *parsed)
{
    yx_bool_parser parser;
    uint8_t opcode = 0x52; /* i64.ne, for a bare integer. */
    int64_t left, right = 0;
    if (!condition || !parsed) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    if (!yx_integer_constant(&parser, &left)) return false;
    yx_bool_skip_space(&parser);
    if (parser.at[0] == '=' && parser.at[1] == '=') {
        opcode = 0x51; parser.at += 2;
    } else if (parser.at[0] == '!' && parser.at[1] == '=') {
        opcode = 0x52; parser.at += 2;
    } else if (parser.at[0] == '<' && parser.at[1] == '=') {
        opcode = 0x57; parser.at += 2;
    } else if (parser.at[0] == '>' && parser.at[1] == '=') {
        opcode = 0x59; parser.at += 2;
    } else if (parser.at[0] == '<') {
        opcode = 0x53; ++parser.at;
    } else if (parser.at[0] == '>') {
        opcode = 0x55; ++parser.at;
    } else if (*parser.at) {
        return false;
    } else {
        parsed->integer_comparison = true;
        parsed->integer_left = left;
        parsed->integer_right = right;
        parsed->integer_opcode = opcode;
        return true;
    }
    if (!yx_integer_constant(&parser, &right)) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at) return false;
    parsed->integer_comparison = true;
    parsed->integer_left = left;
    parsed->integer_right = right;
    parsed->integer_opcode = opcode;
    return true;
}

static const char *yx_integer_read_name(uint8_t type)
{
    static const char *const names[] = {
        "uint8", "uint16", "uint32", "int8", "int16", "int32"
    };
    return type < sizeof(names) / sizeof(names[0]) ? names[type] : NULL;
}

/* Keep this shape to one constant offset and one constant comparison. The
 * dynamic-read WASM and more complex expressions have different layouts. */
static bool yx_condition_integer_read(const char *condition,
                                      yx_ser_rule *parsed)
{
    yx_bool_parser parser;
    int64_t offset, value;
    uint8_t opcode, type;
    if (!condition || !parsed) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    for (type = 0; type < 6; ++type)
        if (yx_bool_keyword(&parser, yx_integer_read_name(type))) break;
    if (type == 6) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at++ != '(' ||
        !yx_integer_constant(&parser, &offset)) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at++ != ')') return false;
    yx_bool_skip_space(&parser);
    if (parser.at[0] == '=' && parser.at[1] == '=') {
        opcode = 0x51; parser.at += 2;
    } else if (parser.at[0] == '!' && parser.at[1] == '=') {
        opcode = 0x52; parser.at += 2;
    } else if (parser.at[0] == '<' && parser.at[1] == '=') {
        opcode = 0x57; parser.at += 2;
    } else if (parser.at[0] == '>' && parser.at[1] == '=') {
        opcode = 0x59; parser.at += 2;
    } else if (parser.at[0] == '<') {
        opcode = 0x53; ++parser.at;
    } else if (parser.at[0] == '>') {
        opcode = 0x55; ++parser.at;
    } else return false;
    if (!yx_integer_constant(&parser, &value)) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at) return false;
    parsed->integer_read_comparison = true;
    parsed->integer_read_type = type;
    parsed->integer_read_offset = offset;
    parsed->integer_right = value;
    parsed->integer_opcode = opcode;
    return true;
}

/* VT permutation variants are compile-time integers, but YARA-X retains
 * their comparison in WASM instead of folding it to a boolean. */
static bool yx_vt_permutation_operand(yx_bool_parser *parser,
                                       int64_t *value, bool *is_enum)
{
    static const struct { const char *name; int64_t value; } variants[] = {
        {"ALL", 31}, {"TYPO", 1}, {"HOMOGLYPH", 2},
        {"HYPHENATION", 4}, {"SUBDOMAIN", 8}, {"BITSQUATTING", 16}
    };
    static const char prefix[] = "vt.Domain.Permutation.";
    yx_bool_skip_space(parser);
    if (strncmp((const char *) parser->at, prefix,
                sizeof(prefix) - 1) == 0) {
        const unsigned char *name = parser->at + sizeof(prefix) - 1;
        for (size_t i = 0; i < sizeof(variants) / sizeof(variants[0]); ++i) {
            size_t length = strlen(variants[i].name);
            if (strncmp((const char *) name, variants[i].name, length) == 0 &&
                !isalnum(name[length]) && name[length] != '_') {
                parser->at = name + length;
                *value = variants[i].value;
                *is_enum = true;
                return true;
            }
        }
        return false;
    }
    *is_enum = false;
    return yx_integer_literal(parser, value);
}

static bool yx_condition_vt_permutation(const char *condition,
                                         yx_ser_rule *parsed)
{
    yx_bool_parser parser;
    bool left_enum = false, right_enum = false;
    uint8_t opcode;
    int64_t left, right;
    if (!condition || !parsed) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    if (!yx_vt_permutation_operand(&parser, &left, &left_enum)) return false;
    yx_bool_skip_space(&parser);
    if (parser.at[0] == '=' && parser.at[1] == '=') {
        opcode = 0x51; parser.at += 2;
    } else if (parser.at[0] == '!' && parser.at[1] == '=') {
        opcode = 0x52; parser.at += 2;
    } else if (parser.at[0] == '<' && parser.at[1] == '=') {
        opcode = 0x57; parser.at += 2;
    } else if (parser.at[0] == '>' && parser.at[1] == '=') {
        opcode = 0x59; parser.at += 2;
    } else if (parser.at[0] == '<') {
        opcode = 0x53; ++parser.at;
    } else if (parser.at[0] == '>') {
        opcode = 0x55; ++parser.at;
    } else return false;
    if (!yx_vt_permutation_operand(&parser, &right, &right_enum) ||
        left_enum == right_enum) return false;
    yx_bool_skip_space(&parser);
    if (*parser.at) return false;
    parsed->vt_imported = true;
    parsed->integer_comparison = true;
    parsed->integer_left = left;
    parsed->integer_right = right;
    parsed->integer_opcode = opcode;
    return true;
}

static bool yx_filesize_expression(yx_bool_parser *parser,
                                   yx_ser_rule *parsed)
{
    uint8_t opcode = 0x52;
    int64_t right = 0;
    if (!parser || !parsed || !yx_bool_keyword(parser, "filesize"))
        return false;
    yx_bool_skip_space(parser);
    if (*parser->at == '+' || *parser->at == '-') {
        parsed->filesize_arithmetic = true;
        parsed->filesize_arith_opcode = *parser->at == '+' ? 0x7c : 0x7d;
        ++parser->at;
        /* Only one multiplicative term binds to filesize. Further additive,
         * shift or bitwise operators associate to the left, as in
         * `(filesize - 1) - 1`, which this codec cannot express. */
        if (!yx_integer_multiplicative(parser, &parsed->filesize_arith_operand))
            return false;
        yx_bool_skip_space(parser);
        if (*parser->at == '+' || *parser->at == '-' || *parser->at == '|' ||
            *parser->at == '^' || *parser->at == '&' ||
            (parser->at[0] == '<' && parser->at[1] == '<') ||
            (parser->at[0] == '>' && parser->at[1] == '>'))
            return false;
    }
    if (parser->at[0] == '=' && parser->at[1] == '=') {
        opcode = 0x51; parser->at += 2;
    } else if (parser->at[0] == '!' && parser->at[1] == '=') {
        opcode = 0x52; parser->at += 2;
    } else if (parser->at[0] == '<' && parser->at[1] == '=') {
        opcode = 0x57; parser->at += 2;
    } else if (parser->at[0] == '>' && parser->at[1] == '=') {
        opcode = 0x59; parser->at += 2;
    } else if (parser->at[0] == '<') {
        opcode = 0x53; ++parser->at;
    } else if (parser->at[0] == '>') {
        opcode = 0x55; ++parser->at;
    } else {
        parsed->filesize_comparison = true;
        parsed->integer_right = 0;
        parsed->integer_opcode = opcode;
        return true;
    }
    if (!yx_integer_constant(parser, &right)) return false;
    parsed->filesize_comparison = true;
    parsed->integer_right = right;
    parsed->integer_opcode = opcode;
    return true;
}

static bool yx_reversed_filesize_expression(yx_bool_parser *parser,
                                            yx_ser_rule *parsed)
{
    int64_t literal;
    uint8_t opcode;
    size_t groups = 0;
    if (!parser || !parsed || !yx_integer_constant(parser, &literal))
        return false;
    yx_bool_skip_space(parser);
    if (parser->at[0] == '=' && parser->at[1] == '=') {
        opcode = 0x51; parser->at += 2;
    } else if (parser->at[0] == '!' && parser->at[1] == '=') {
        opcode = 0x52; parser->at += 2;
    } else if (parser->at[0] == '<' && parser->at[1] == '=') {
        opcode = 0x57; parser->at += 2;
    } else if (parser->at[0] == '>' && parser->at[1] == '=') {
        opcode = 0x59; parser->at += 2;
    } else if (parser->at[0] == '<') {
        opcode = 0x53; ++parser->at;
    } else if (parser->at[0] == '>') {
        opcode = 0x55; ++parser->at;
    } else return false;
    yx_bool_skip_space(parser);
    while (*parser->at == '(') {
        if (++groups > 256) return false;
        ++parser->at;
        yx_bool_skip_space(parser);
    }
    if (!yx_bool_keyword(parser, "filesize")) return false;
    while (groups > 0) {
        --groups;
        yx_bool_skip_space(parser);
        if (*parser->at != ')') return false;
        ++parser->at;
    }
    parsed->filesize_comparison = true;
    parsed->filesize_literal_first = true;
    parsed->integer_right = literal;
    parsed->integer_opcode = opcode;
    return true;
}

static bool yx_condition_filesize_plain(const char *condition,
                                        yx_ser_rule *parsed)
{
    yx_bool_parser parser;
    yx_ser_rule original;
    size_t groups = 0;
    if (!condition || !parsed) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    original = *parsed;
    if (yx_reversed_filesize_expression(&parser, parsed)) {
        yx_bool_skip_space(&parser);
        if (*parser.at == 0) return true;
    }
    *parsed = original;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    yx_bool_skip_space(&parser);
    while (*parser.at == '(') {
        if (++groups > 256) return false;
        ++parser.at;
        yx_bool_skip_space(&parser);
    }
    if (!yx_filesize_expression(&parser, parsed)) {
        *parsed = original;
        parser.at = (const unsigned char *) condition;
        parser.depth = 0;
        yx_bool_skip_space(&parser);
        for (size_t i = 0; i < groups; ++i) {
            ++parser.at;
            yx_bool_skip_space(&parser);
        }
        if (!yx_reversed_filesize_expression(&parser, parsed)) return false;
    }
    while (groups > 0) {
        --groups;
        yx_bool_skip_space(&parser);
        if (*parser.at != ')') return false;
        ++parser.at;
    }
    yx_bool_skip_space(&parser);
    return *parser.at == 0;
}

static bool yx_condition_filesize_identity(const char *condition,
                                           yx_ser_rule *parsed)
{
    yx_bool_parser parser;
    yx_ser_rule candidate;
    if (!condition || !parsed) return false;
    parser.at = (const unsigned char *) condition;
    parser.depth = 0;
    candidate = *parsed;
    if (yx_bool_keyword(&parser, "true") &&
        yx_bool_keyword(&parser, "and") &&
        yx_condition_filesize_plain((const char *) parser.at, &candidate)) {
        candidate.filesize_identity_blocks = 1;
        *parsed = candidate;
        return true;
    }
    parser.at = (const unsigned char *) condition;
    candidate = *parsed;
    if (yx_bool_keyword(&parser, "false") &&
        yx_bool_keyword(&parser, "or") &&
        yx_condition_filesize_plain((const char *) parser.at, &candidate)) {
        candidate.filesize_identity_blocks = 2;
        *parsed = candidate;
        return true;
    }
    for (const char *split = condition; *split; ++split) {
        uint8_t blocks = 0;
        size_t left_length;
        char *left;
        if (split != condition &&
            !isspace((unsigned char) split[-1]) && split[-1] != ')')
            continue;
        parser.at = (const unsigned char *) split;
        if (yx_bool_keyword(&parser, "and") &&
            yx_bool_keyword(&parser, "true"))
            blocks = 1;
        else {
            parser.at = (const unsigned char *) split;
            if (yx_bool_keyword(&parser, "or") &&
                yx_bool_keyword(&parser, "false"))
                blocks = 2;
        }
        if (!blocks) continue;
        yx_bool_skip_space(&parser);
        if (*parser.at) continue;
        left_length = (size_t) (split - condition);
        left = malloc(left_length + 1);
        if (!left) return false;
        memcpy(left, condition, left_length);
        left[left_length] = 0;
        candidate = *parsed;
        bool recognized = yx_condition_filesize_plain(left, &candidate);
        free(left);
        if (recognized) {
            candidate.filesize_identity_blocks = blocks;
            *parsed = candidate;
            return true;
        }
    }
    return false;
}

