        parser.depth = 0;
        if (!yx_bool_keyword(&parser, is_or ? "or" : "and")) continue;
        right_start = (const char *) parser.at;
        while (isspace((unsigned char) *right_start)) ++right_start;
        right_length = strlen(right_start);
        while (right_length &&
               isspace((unsigned char) right_start[right_length - 1]))
            --right_length;
        if (right_length < 2 || right_start[0] != '(' ||
            right_start[right_length - 1] != ')') continue;
        left_length = (size_t) (split - condition);
        left = malloc(left_length + 1);
