    const YRX_PATTERN *pattern = &rule->patterns[0];
    uint8_t literal[4], short_atom[3], code[40];
    uint8_t ac[YX_NOCASE_PATTERN_AC_PREFILTER_LENGTH];
    uint8_t wasm[sizeof(yx_single_text_pattern_wasm)];
    const uint8_t *atoms[2];
    size_t widths[2], code_at = 0, code_length, ac_length;
    size_t atom_count = 2;
    bool right_plus, short_first_plus, short_middle_plus, short_last_plus;
    bool short_optional;
    bool short_star, single_star;
    bool plus_prefix_atom;
    bool star_two_atoms;
    bool star_second_prefix_atom;
    bool star_third_two_atoms;
