bool yx_ser_regexp_literal_atoms(const char *regexp)
{
    if(!regexp)return false;
    /* Scanner creation asks for every regexp pattern; memoized per text. */
    size_t length=strlen(regexp),stored=0;
    uint64_t tag=YX_MEMO_TAG(YX_MEMO_REGEXP_LITERAL_ATOMS,0,0);
    const void *hit=yx_compile_memo_find(tag,regexp,length,&stored);
    bool valid;
    if(hit&&stored==sizeof(valid)){memcpy(&valid,hit,sizeof(valid));return valid;}
    yx_tr_parser parser={.text=(const uint8_t *)regexp,.length=length};
    yx_tr_node *root=yx_tr_expression(&parser),*node=root;
    valid=root&&!parser.failed&&!parser.oom&&parser.at==parser.length;
    bool keep=root&&!parser.oom;
    if(valid&&node->kind==YX_TR_CAPTURE)node=node->children[0];
    if(valid&&node->kind==YX_TR_LITERAL)valid=node->length!=0;
    else if(valid&&node->kind==YX_TR_ALT) {
        for(size_t i=0;i<node->count;++i)
            if(node->children[i]->kind!=YX_TR_LITERAL||!node->children[i]->length)valid=false;
    } else valid=false;
    yx_tr_destroy(root);
    if(keep)yx_compile_memo_store(tag,regexp,length,&valid,sizeof(valid));
    return valid;
}

